class Solution:
    def encode(self, strs: List[str]) -> str:
        out = []
        for s in strs:
            escaped = s.replace("\\", "\\\\").replace(";", "\\;")
            out.append(escaped + ";")
        return "".join(out)

    def decode(self, s: str) -> List[str]:
        res, cur, i = [], [], 0
        while i < len(s):
            if s[i] == "\\":
                cur.append(s[i + 1])
                i += 2
            elif s[i] == ";":
                res.append("".join(cur))
                cur = []
                i += 1
            else:
                cur.append(s[i])
                i += 1
        return res

class Solution:
    def encode(self, strs: List[str]) -> str:
        out = []
        for s in strs:
            out.append(str(len(s)) + "#" + s)
        return "".join(out)

    def decode(self, s: str) -> List[str]:
        res, i = [], 0
        while i < len(s):
            j = i
            while s[j] != "#":
                j += 1
            length = int(s[i:j])
            res.append(s[j + 1 : j + 1 + length])
            i = j + 1 + length
        return res

